const s = $getWorkflowStaticData('global');
const now = Math.floor(Date.now() / 1000);
const lastRun = s.lastRun || (now - 7 * 24 * 3600);

s.pendingRun = now;

return [{
  json: {
    lastRun,
    now,
    cutoffIso: new Date(lastRun * 1000).toISOString()
  }
}];

// Finance brief sources: 3 Polish finance YouTube channels + finance-news RSS
// (Bankier.pl Polish + MarketWatch global). Fetch is done by the HTTP node downstream.
// NOTE: env access is blocked on this n8n (N8N_BLOCK_ENV_ACCESS_IN_NODE) -> literals.

const lastRun = $('Init state').first().json.lastRun;

const channelIds = [
  'UCgw_3Epv7swquSZyMDjYHTg', // @DNARynkow
  'UCtTpDSRTegHewCxP9GTUaXQ', // @FxMag
  'UCG4T6bLDq2TdAdRAp2GDOCw'  // @zawodinwestor
];

const newsFeeds = [
  'https://www.bankier.pl/rss/wiadomosci.xml',                       // Polish finance
  'https://feeds.content.dowjones.io/public/rss/mw_topstories'       // MarketWatch (global)
];

const out = [];
for (const cid of channelIds) {
  const id = String(cid || '').trim();
  if (!id.startsWith('UC')) continue;
  out.push({ json: { kind: 'yt', url: `https://www.youtube.com/feeds/videos.xml?channel_id=${encodeURIComponent(id)}` } });
}
for (const url of newsFeeds) {
  out.push({ json: { kind: 'news', url } });
}

if (!out.length) throw new Error('No finance source URLs built');
return out;

// Parse "Fetch source" responses: YouTube Atom feeds (<entry>) and RSS news feeds (<item>).
// Dedupe + filter by lastRun + seenIds. No network here (sandbox-safe).

function decodeXml(value) {
  return String(value || '')
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&#x[0-9a-f]+;/gi, ' ');
}
function textBetween(source, tag) {
  const m = source.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i'));
  return m ? decodeXml(m[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').trim()) : '';
}
function attr(source, tag, name) {
  const m = source.match(new RegExp(`<${tag}[^>]*\\b${name}="([^"]*)"`, 'i'));
  return m ? decodeXml(m[1]) : '';
}
function stripHtml(value) {
  return String(value || '')
    .replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}
// short, stable id from a long guid/URL so the LLM round-trips it reliably (for the id->url join)
function shortId(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return 'n' + h.toString(36);
}

const lastRun = $('Init state').first().json.lastRun;
const s = $getWorkflowStaticData('global');
const seenIds = new Set(s.seenIds || []);
const unique = new Map();

for (const entry of $input.all()) {
  const body = entry.json.data;
  const text = typeof body === 'string' ? body : JSON.stringify(body || '');
  if (!text) continue;

  if (/<entry[\s>]/i.test(text)) {
    // YouTube Atom
    for (const node of (text.match(/<entry>[\s\S]*?<\/entry>/gi) || [])) {
      const id = textBetween(node, 'yt:videoId') || textBetween(node, 'id').replace(/^yt:video:/, '');
      const published = textBetween(node, 'published');
      const epoch = Math.floor(Date.parse(published) / 1000);
      if (!id || !epoch || epoch <= lastRun || seenIds.has(id)) continue;
      unique.set(`yt:${id}`, {
        source: 'yt', id,
        title: textBetween(node, 'title'),
        url: `https://www.youtube.com/watch?v=${id}`,
        published, channel: textBetween(node, 'name'),
        snippet: stripHtml(textBetween(node, 'media:description')).slice(0, 800)
      });
    }
  } else if (/<item[\s>]/i.test(text)) {
    // RSS news
    for (const node of (text.match(/<item[\s>][\s\S]*?<\/item>/gi) || [])) {
      const link = textBetween(node, 'link') || attr(node, 'guid', 'isPermaLink') && textBetween(node, 'guid');
      const guid = textBetween(node, 'guid') || link;
      const raw = String(guid || link || '').trim();
      if (!raw) continue;
      const id = shortId(raw); // short stable id (long guids/URLs get mangled by the LLM)
      if (seenIds.has(id)) continue;
      const pub = textBetween(node, 'pubDate');
      const epoch = Math.floor(Date.parse(pub) / 1000);
      if (epoch && epoch <= lastRun) continue; // skip clearly-old; undated items pass (seenIds dedups)
      unique.set(`news:${id}`, {
        source: 'news', id,
        title: stripHtml(textBetween(node, 'title')),
        url: link || raw,
        published: pub,
        snippet: stripHtml(textBetween(node, 'description')).slice(0, 800)
      });
    }
  }
}

return [...unique.values()].map(json => ({ json }));

// Finance filter: rank candidate items against a finance/markets interest profile.
// NOTE: env access is blocked on this n8n -> literals.

const items = $input.all().map(item => item.json);
const topN = 8;
const interestProfile = 'Inwestor/trader sledzacy rynki finansowe: akcje (GPW i rynki swiatowe), indeksy, makroekonomia, stopy procentowe i banki centralne (NBP, Fed, EBC), waluty (PLN, EUR, USD), surowce (ropa, zloto, gaz), obligacje, wyniki spolek, geopolityka wplywajaca na rynki. Preferuj konkret rynkowy i analize ponad clickbait, reklamy i tresci poradnikowe ogolne.';

if (!items.length) throw new Error('No candidate items found');

const system = `Jestes filtrem tresci dla cotygodniowego briefu finansowego. Profil odbiorcy:
${interestProfile}

Otrzymasz liste pozycji: id, source, title, snippet.
Zwroc wylacznie JSON:
{"selected":[{"id":"...","reason":"<max 12 slow>"}]}
Zasady: maksymalnie ${topN} pozycji; odrzuc reklamy, clickbait i duplikaty tematyczne; preferuj zgodnosc z profilem i swiezosc rynkowa. Bez komentarza poza JSON.`;

return [{
  json: {
    candidateItems: items,
    requestBody: {
      contents: [{
        role: 'user',
        parts: [{ text: JSON.stringify(items.map(({ id, source, title, snippet }) => ({ id, source, title, snippet }))) }]
      }],
      systemInstruction: { parts: [{ text: system }] },
      generationConfig: {
        temperature: 0.1,
        maxOutputTokens: 8192,
        thinkingConfig: { thinkingBudget: 0 },
        responseMimeType: 'application/json'
      }
    }
  }
}];

function contentFrom(response) {
  return response?.choices?.[0]?.message?.content
    || response?.candidates?.[0]?.content?.parts?.map(part => part.text || '').join('')
    || response?.message?.content
    || response?.text
    || response?.data
    || '';
}

const input = $input.first().json;
const body = typeof input === 'string' ? JSON.parse(input) : input;
const raw = contentFrom(body);
let parsed;

try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) {
  throw new Error(`LLM filter did not return valid JSON: ${error.message}. Raw: ${String(raw).slice(0, 500)}`);
}

const selected = new Map((parsed.selected || []).map(item => [String(item.id), item.reason || '']));
const candidates = $('Build filter input').first().json.candidateItems || [];

return candidates
  .filter(item => selected.has(String(item.id)))
  .map(item => ({ json: { ...item, reason: selected.get(String(item.id)) } }));

// Finance enrich: build content from title + source + snippet (no article fetch — RSS
// descriptions / video metadata are enough and avoid paywall/JS-fetch failures).

return $input.all().map(entry => {
  const item = entry.json;
  const content = [
    item.title,
    item.channel ? `Kanal: ${item.channel}` : (item.source === 'news' ? 'Zrodlo: wiadomosci rynkowe' : ''),
    item.snippet
  ].filter(Boolean).join('\n\n').slice(0, 6000);
  return { json: { ...item, content } };
});

const items = $input.all().map(item => item.json);

if (!items.length) throw new Error('No enriched items to summarize');

const system = `Stresc ponizsza tresc do 2-4 punktow faktograficznych.
Zasady:
- Tylko fakty merytoryczne obecne w tresci; nie dodawaj wiedzy zewnetrznej; nie spekuluj.
- POMIJAJ fragmenty sponsorskie, reklamowe, prosby o subskrypcje i linki.
- Pierwszy punkt ma byc trescia (o czym to jest) — NIGDY "film/material dostepny na kanale X". Jesli tresci jest malo, napisz jedno konkretne zdanie o temacie na bazie tytulu i opisu.
- Kazdy punkt zwiezly, konkretny; zachowaj liczby i nazwy, jesli sa.
Zwroc JSON: {"summaries":[{"id":"...","source_url":"...","title":"...","bullets":["...","..."]}]}`;

return [{
  json: {
    enrichedItems: items,
    requestBody: {
      contents: [{
        role: 'user',
        parts: [{
          text: JSON.stringify(items.map(({ id, source, title, url, content }) => ({
            id,
            source,
            title,
            source_url: url,
            content
          })))
        }]
      }],
      systemInstruction: { parts: [{ text: system }] },
      generationConfig: {
        temperature: 0.1,
        maxOutputTokens: 8192,
        thinkingConfig: { thinkingBudget: 0 },
        responseMimeType: 'application/json'
      }
    }
  }
}];

function contentFrom(response) {
  return response?.choices?.[0]?.message?.content
    || response?.candidates?.[0]?.content?.parts?.map(part => part.text || '').join('')
    || response?.message?.content
    || response?.text
    || response?.data
    || '';
}

const body = $input.first().json;
const raw = contentFrom(body);
let parsed;

try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) {
  throw new Error(`LLM summaries did not return valid JSON: ${error.message}. Raw: ${String(raw).slice(0, 500)}`);
}

const summaries = parsed.summaries || [];
return summaries.map(summary => ({ json: summary }));

// Two-host conversational finance podcast script (Polish). Produces a natural dialogue
// between a male host (A) and a female expert (B), in the style of a Polish economic podcast.
// NOTE: env access is blocked on this n8n -> literals.

const summaries = $input.all().map(item => item.json);
if (!summaries.length) throw new Error('No summaries available for podcast script');

const system = `Tworzysz odcinek PODCASTU EKONOMICZNEGO po polsku — naturalna rozmowe dwojga prowadzacych:
- A: GOSPODARZ (glos meski) — prowadzi, wprowadza tematy, dopytuje, syntetyzuje, reaguje.
- B: EKSPERTKA (glos damski) — analizuje, dodaje kontekst, liczby i konsekwencje, czasem polemizuje.
Styl jak dobry polski podcast ekonomiczny: swobodny ale merytoryczny, analityczny, konkretny, z danymi (liczby, procenty, nazwy spolek/instytucji). To ma byc PRAWDZIWA ROZMOWA — reaguja na siebie, dopytuja, rozwijaja watki, czasem sie nie zgadzaja — a nie dwa osobne monologi.
Struktura: krotkie intro (przywitanie + zapowiedz tematow) -> 3-5 tematow rynkowych wg waznosci, kazdy rozwijany w kilku wymianach zdan -> krotkie podsumowanie i pozegnanie.
DLUGOSC — TRZYMAJ SIE SCISLE: napisz DOKLADNIE 20-24 wypowiedzi (turns), naprzemiennie A i B. KAZDA wypowiedz ma miec 30-45 slow (2-4 zdania) — nie krotsze. To daje odcinek okolo 6 minut (~750-820 slow lacznie, max 4700 znakow). Wybierzcie 3-4 najwazniejsze tematy i rozwijajcie kazdy w 4-6 wymianach. Pierwsza wypowiedz to intro (przywitanie + zapowiedz), ostatnia to krotkie zamkniecie i pozegnanie.
Zasady twarde:
- Opieraj sie WYLACZNIE na dostarczonych punktach; nie zmyslaj faktow ani liczb; nie dodawaj wiedzy zewnetrznej.
- Nie podawaj porad inwestycyjnych ani rekomendacji kupna/sprzedazy.
- Kazda kwestia (turn) to jedna naturalna wypowiedz, 1-4 zdania; naprzemiennie A i B, ale nie sztywno.
- W polu "text" wpisz WYLACZNIE wypowiadane slowa — bez imion, didaskaliow, oznaczen mowcy czy URL.
Zwroc WYLACZNIE JSON: {"turns":[{"speaker":"A","text":"..."},{"speaker":"B","text":"..."}],"show_notes":[{"title":"...","url":"..."}]}`;

return [{
  json: {
    summaries,
    requestBody: {
      contents: [{ role: 'user', parts: [{ text: JSON.stringify({ summaries }) }] }],
      systemInstruction: { parts: [{ text: system }] },
      generationConfig: {
        temperature: 0.5,
        maxOutputTokens: 16384,
        thinkingConfig: { thinkingBudget: 2048 },
        responseMimeType: 'application/json'
      }
    }
  }
}];

// Parse the dialogue script JSON: { turns: [{speaker, text}], show_notes: [...] }.

function contentFrom(response) {
  return response?.candidates?.[0]?.content?.parts?.map(part => part.text || '').join('')
    || response?.choices?.[0]?.message?.content
    || response?.text
    || '';
}

const body = $input.first().json;
const raw = contentFrom(body);
let parsed;
try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) {
  throw new Error(`Podcast script not valid JSON: ${error.message}. Raw: ${String(raw).slice(0, 500)}`);
}

const turns = (parsed.turns || [])
  .map(t => ({ speaker: String(t.speaker || 'A').toUpperCase() === 'B' ? 'B' : 'A', text: String(t.text || '').trim() }))
  .filter(t => t.text);

if (!turns.length) throw new Error('Podcast script has no dialogue turns');

return [{
  json: {
    turns,
    show_notes: parsed.show_notes || [],
    generatedAt: new Date().toISOString()
  }
}];

// Build the ElevenLabs Text-to-Dialogue request from the dialogue turns: speaker A -> male
// voice, speaker B -> female voice. One API call returns one two-voice mp3 (no concat).
// Named "Build TTS request" so the shared signing/upload nodes work unchanged.

const VOICE_A = 'onwK4e9ZLuTAKqWW03F9'; // male — Daniel (Steady Broadcaster)
const VOICE_B = 'EXAVITQu4vr4xnSDxMaL'; // female — Sarah (Professional)
const MAX_CHARS = 4700;                 // ElevenLabs Text-to-Dialogue hard limit is 5000 chars/request

const input = $input.first().json;
const generatedAt = input.generatedAt || new Date().toISOString();
const ts = Math.floor(Date.parse(generatedAt) / 1000);
const bucket = 'dcs-ai-news-briefs';
const objectName = `fin_podcast_${ts}.mp3`;

const inputs = [];
let total = 0;
for (const t of input.turns || []) {
  const text = String(t.text || '').trim();
  if (!text) continue;
  if (total + text.length > MAX_CHARS) break;
  total += text.length;
  inputs.push({ text, voice_id: t.speaker === 'B' ? VOICE_B : VOICE_A });
}

if (!inputs.length) throw new Error('No dialogue turns to synthesize');

return [{
  json: {
    chars: total,
    turns: inputs.length,
    show_notes: input.show_notes || [],
    generatedAt, ts, bucket, objectName,
    gcsUri: `gs://${bucket}/${objectName}`,
    requestBody: { model_id: 'eleven_v3', inputs }
  }
}];

// Build a GCS V4 (GOOG4-RSA-SHA256) signed-URL "string to sign". The RSA signature is
// produced by IAM signBlob (next node), so no private key is ever stored. The only crypto
// primitive needed client-side is SHA-256 of the canonical request, vendored below so this
// works in the restricted n8n Code-node sandbox (no Node modules, no Buffer).

function sha256hex(ascii) {
  function rotr(n, x) { return (x >>> n) | (x << (32 - n)); }
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  let h0=0x6a09e667,h1=0xbb67ae85,h2=0x3c6ef372,h3=0xa54ff53a,h4=0x510e527f,h5=0x9b05688c,h6=0x1f83d9ab,h7=0x5be0cd19;
  const bytes = [];
  for (let i = 0; i < ascii.length; i++) {
    let c = ascii.charCodeAt(i);
    if (c < 128) bytes.push(c);
    else if (c < 2048) bytes.push(192 | (c >> 6), 128 | (c & 63));
    else bytes.push(224 | (c >> 12), 128 | ((c >> 6) & 63), 128 | (c & 63));
  }
  const l = bytes.length;
  bytes.push(0x80);
  while ((bytes.length % 64) !== 56) bytes.push(0);
  const bl = l * 8;
  for (let i = 7; i >= 0; i--) bytes.push((Math.floor(bl / Math.pow(2, i * 8))) & 0xff);
  const w = new Array(64);
  for (let j = 0; j < bytes.length; j += 64) {
    for (let i = 0; i < 16; i++) w[i] = (bytes[j+i*4] << 24) | (bytes[j+i*4+1] << 16) | (bytes[j+i*4+2] << 8) | (bytes[j+i*4+3]);
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(7, w[i-15]) ^ rotr(18, w[i-15]) ^ (w[i-15] >>> 3);
      const s1 = rotr(17, w[i-2]) ^ rotr(19, w[i-2]) ^ (w[i-2] >>> 10);
      w[i] = (w[i-16] + s0 + w[i-7] + s1) | 0;
    }
    let a=h0,b=h1,c=h2,d=h3,e=h4,f=h5,g=h6,h=h7;
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(6,e) ^ rotr(11,e) ^ rotr(25,e);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[i] + w[i]) | 0;
      const S0 = rotr(2,a) ^ rotr(13,a) ^ rotr(22,a);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) | 0;
      h=g; g=f; f=e; e=(d+t1)|0; d=c; c=b; b=a; a=(t1+t2)|0;
    }
    h0=(h0+a)|0; h1=(h1+b)|0; h2=(h2+c)|0; h3=(h3+d)|0; h4=(h4+e)|0; h5=(h5+f)|0; h6=(h6+g)|0; h7=(h7+h)|0;
  }
  const toHex = n => ('00000000' + ((n >>> 0).toString(16))).slice(-8);
  return [h0,h1,h2,h3,h4,h5,h6,h7].map(toHex).join('');
}

function b64(str) {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const bytes = [];
  for (let i = 0; i < str.length; i++) {
    let c = str.charCodeAt(i);
    if (c < 128) bytes.push(c);
    else if (c < 2048) bytes.push(192 | (c >> 6), 128 | (c & 63));
    else bytes.push(224 | (c >> 12), 128 | ((c >> 6) & 63), 128 | (c & 63));
  }
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const b0 = bytes[i], b1 = bytes[i+1], b2 = bytes[i+2];
    out += chars[b0 >> 2];
    out += chars[((b0 & 3) << 4) | ((b1 || 0) >> 4)];
    out += i + 1 < bytes.length ? chars[((b1 & 15) << 2) | ((b2 || 0) >> 6)] : '=';
    out += i + 2 < bytes.length ? chars[b2 & 63] : '=';
  }
  return out;
}

function enc(s) {
  return encodeURIComponent(s).replace(/[!*'()]/g, c => '%' + c.charCodeAt(0).toString(16).toUpperCase());
}
function encPath(p) { return p.split('/').map(enc).join('/'); }
function pad(n) { return String(n).padStart(2, '0'); }

const carry = $('Build TTS request').first().json;
const sa = 'maths-vm-sa@data-concept-studio.iam.gserviceaccount.com';
const bucket = carry.bucket;
const object = carry.objectName;
const ttl = Math.min(Number(604800), 604800);
const region = 'auto';

const now = new Date();
const datestamp = `${now.getUTCFullYear()}${pad(now.getUTCMonth() + 1)}${pad(now.getUTCDate())}`;
const reqTs = `${datestamp}T${pad(now.getUTCHours())}${pad(now.getUTCMinutes())}${pad(now.getUTCSeconds())}Z`;
const scope = `${datestamp}/${region}/storage/goog4_request`;
const credential = `${sa}/${scope}`;
const host = 'storage.googleapis.com';
const canonicalUri = `/${bucket}/${encPath(object)}`;

const qsPairs = [
  ['X-Goog-Algorithm', 'GOOG4-RSA-SHA256'],
  ['X-Goog-Credential', credential],
  ['X-Goog-Date', reqTs],
  ['X-Goog-Expires', String(ttl)],
  ['X-Goog-SignedHeaders', 'host']
].map(([k, v]) => [enc(k), enc(v)]).sort((a, b) => (a[0] < b[0] ? -1 : 1));
const canonicalQuery = qsPairs.map(([k, v]) => `${k}=${v}`).join('&');

const canonicalRequest = ['GET', canonicalUri, canonicalQuery, `host:${host}\n`, 'host', 'UNSIGNED-PAYLOAD'].join('\n');
const stringToSign = ['GOOG4-RSA-SHA256', reqTs, scope, sha256hex(canonicalRequest)].join('\n');

return [{
  json: {
    ...carry,
    signer: sa,
    baseUrl: `https://${host}${canonicalUri}?${canonicalQuery}`,
    payloadB64: b64(stringToSign)
  }
}];

// Turn the IAM signBlob response into the final V4 signed URL.
// signedBlob is base64 of the RSA-SHA256 signature; X-Goog-Signature must be lowercase hex.

const carry = $('Build signed url').first().json;
const resp = $input.first().json;
const signedBlobB64 = resp.signedBlob;

if (!signedBlobB64) {
  throw new Error(`signBlob returned no signedBlob: ${JSON.stringify(resp).slice(0, 300)}`);
}

const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const clean = String(signedBlobB64).replace(/=+$/, '');
let bits = 0, val = 0, hex = '';
for (const ch of clean) {
  val = (val << 6) | chars.indexOf(ch);
  bits += 6;
  if (bits >= 8) {
    bits -= 8;
    hex += ('0' + (((val >> bits) & 0xff).toString(16))).slice(-2);
  }
}

const signedUrl = `${carry.baseUrl}&X-Goog-Signature=${hex}`;

return [{
  json: {
    signedUrl,
    objectName: carry.objectName,
    gcsUri: carry.gcsUri,
    show_notes: carry.show_notes,
    generatedAt: carry.generatedAt,
    ts: carry.ts
  }
}];

// Podcast digest for #finance-news: episode header, topics discussed (linked to sources),
// and the signed audio link (two-voice mp3). NOTE: env blocked -> channel id literal.

const sig = $input.first().json;
const summaries = $('Parse summaries').all().map(i => i.json);
const enriched = $('Build summary input').first().json.enrichedItems || [];
const day = new Date(sig.generatedAt || Date.now()).toISOString().slice(0, 10);

const norm = t => String(t || '').toLowerCase().replace(/\s+/g, ' ').trim();
const urlById = new Map(enriched.map(i => [String(i.id), i.url]));
const urlByTitle = new Map(enriched.map(i => [norm(i.title), i.url]));
function cleanLabel(s) { return String(s || '').replace(/[*_~`<>|]/g, '').trim(); }
function cleanUrl(u) { return /^https?:\/\//i.test(String(u || '')) ? String(u).trim() : ''; }

const lines = summaries.slice(0, 8).map(s => {
  const title = cleanLabel(s.title || 'temat');
  const url = cleanUrl(urlById.get(String(s.id)) || urlByTitle.get(norm(s.title)) || s.source_url);
  return url ? `• <${url}|${title}>` : `• ${title}`;
});

const body = lines.length ? lines.join('\n') : '_Brak nowych tematow w tym tygodniu._';
const text = `🎙️ *Podcast Ekonomiczny — ${day}*\n_Rozmowa dwojga prowadzących o tym, co dzieje się na rynkach._\n\n*W tym odcinku:*\n${body}\n\n🎧 <${sig.signedUrl}|Posłuchaj / pobierz odcinek> · link ważny 7 dni`;

const processedIds = enriched.map(i => i.id);

return [{
  json: {
    channel: 'C0BBWESNQ4B',
    text,
    processedIds,
    signedUrl: sig.signedUrl
  }
}];

// Commit the run window only after Slack delivery succeeded. Keeps lastRun + the rolling
// seenIds dedupe set. (Episode/RSS state was removed — Slack is the only delivery path.)

const s = $getWorkflowStaticData('global');
const fromSlack = $('Build Slack digest').first().json;
const processedIds = (fromSlack && fromSlack.processedIds) || [];

if (!s.pendingRun) throw new Error('pendingRun missing; refusing to commit lastRun');

s.lastRun = s.pendingRun;
s.seenIds = [...new Set([...(s.seenIds || []), ...processedIds])].slice(-2000);
delete s.pendingRun;

return [{ json: { ok: true, lastRun: s.lastRun, seenCount: s.seenIds.length } }];
